const results = $input.first().json.results || [];
return results.map(r => ({ json: {
  pageId: r.id,
  email: r.properties?.Email?.email || null,
  name: (r.properties?.Name?.title?.[0]?.plain_text) || 'there',
  goal: r.properties?.Goal?.rich_text?.map(t => t.plain_text).join('') || ''
} })).filter(i => i.json.email);
